/**
 * "Blocked by" links between issues of one organization. A row reads
 * "`issue_id` is blocked by `blocker_id`"; the blocker side is joined onto
 * `issues` whenever a caller needs its status or archive state.
 *
 * Must call (do not reimplement): livePredicate, orgPredicate
 */
import { and, asc, eq, inArray, notInArray } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { brandId, toIssue, toIssueDependency } from "./_mappers";
import { listLabelsForIssues } from "./label-repository";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";

function linkPredicate(orgId: OrgId, issueId: IssueId, blockerId: IssueId) {
  return and(
    orgPredicate(issueDependencies.orgId, orgId),
    eq(issueDependencies.issueId, issueId),
    eq(issueDependencies.blockerId, blockerId),
  );
}

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(linkPredicate(orgId, issueId, blockerId))
    .get();
  return row ? toIssueDependency(row) : null;
}

/** Idempotent: an existing link is returned as-is rather than duplicated. */
export async function insertDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
  createdBy: UserId,
): Promise<IssueDependency> {
  getDb()
    .insert(issueDependencies)
    .values({
      orgId,
      issueId,
      blockerId,
      createdBy,
      createdAt: toIsoTimestamp(new Date()),
    })
    .onConflictDoNothing()
    .run();

  const link = await findDependency(orgId, issueId, blockerId);
  if (!link) throw new Error(`Dependency ${issueId} <- ${blockerId} not stored`);
  return link;
}

/** Resolves `true` when a link was deleted, `false` when there was none. */
export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const rows = getDb()
    .delete(issueDependencies)
    .where(linkPredicate(orgId, issueId, blockerId))
    .returning({ issueId: issueDependencies.issueId })
    .all();
  return rows.length > 0;
}

/**
 * Every blocker id of the given issues, regardless of the blockers' status or
 * archive state — the raw edge set cycle detection walks.
 */
export async function listBlockerIds(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly IssueId[]> {
  if (issueIds.length === 0) return [];

  const rows = getDb()
    .select({ blockerId: issueDependencies.blockerId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        inArray(issueDependencies.issueId, [...issueIds]),
      ),
    )
    .all();
  return rows.map((row) => brandId<IssueId>(row.blockerId));
}

/** Ids of every issue `blockerId` blocks. */
export async function listBlockedIssueIds(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ issueId: issueDependencies.issueId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .all();
  return rows.map((row) => brandId<IssueId>(row.issueId));
}

/** Live blocker issues of `issueId`, open or closed, by issue number. */
export async function listBlockerIssues(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(
      issues,
      and(
        eq(issues.id, issueDependencies.blockerId),
        orgPredicate(issues.orgId, orgId),
      ),
    )
    .where(
      and(
        ...compact(
          orgPredicate(issueDependencies.orgId, orgId),
          eq(issueDependencies.issueId, issueId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.issue.id as IssueId),
  );

  return rows.map((row) =>
    toIssue(row.issue, (labels[row.issue.id] ?? []).map((label) => label.id)),
  );
}

/**
 * Blockers of `issueId` that are still open: live and not in a closed status.
 * The completion gate and the unblocked notification both hinge on this set.
 */
export async function listOpenBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ blockerId: issueDependencies.blockerId })
    .from(issueDependencies)
    .innerJoin(
      issues,
      and(
        eq(issues.id, issueDependencies.blockerId),
        orgPredicate(issues.orgId, orgId),
      ),
    )
    .where(
      and(
        ...compact(
          orgPredicate(issueDependencies.orgId, orgId),
          eq(issueDependencies.issueId, issueId),
          livePredicate(issues.archivedAt, {}),
          notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
        ),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();
  return rows.map((row) => brandId<IssueId>(row.blockerId));
}

