/**
 * "Blocked by" links between issues: recording and removing them, the
 * completion gate `IssueService` consults before an issue may become `done`,
 * and the `issue_unblocked` notification sent when a blocker closes.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, notify, subscribe
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived, isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { issueResource, requireFound } from "./_support";
import { notify } from "./notification-service";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";

/** Raised when an issue with at least one open blocker is moved to `done`. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: IssueId,
    readonly blockerIds: readonly IssueId[],
  ) {
    super(
      `Issue ${issueId} is blocked by ${blockerIds.length} open issue(s): ${blockerIds.join(", ")}`,
    );
    this.name = "IssueBlockedError";
  }
}

type BlockerInput = { orgId: OrgId; issueId: IssueId; blockerId: IssueId };

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/** Open: not archived, and neither `done` nor `canceled`. */
function isOpen(issue: Issue): boolean {
  return !isArchived(issue) && !isClosedStatus(issue.status);
}

/** Records "`issueId` is blocked by `blockerId`". Re-adding returns the existing link. */
export async function addBlocker(
  actor: Actor,
  input: BlockerInput,
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  if (issue.id === blocker.id) {
    throw new Error(`Issue ${issue.id} cannot block itself`);
  }

  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    issue.id,
    blocker.id,
  );
  if (existing) return existing;

  if (await isBlockedTransitively(input.orgId, blocker.id, issue.id)) {
    throw new Error(
      `Issue ${blocker.id} already depends on ${issue.id}; blocking would create a cycle`,
    );
  }

  return dependencyRepo.insertDependency(
    input.orgId,
    issue.id,
    blocker.id,
    actor.userId,
  );
}

/** Deletes the link; `false` when there was none. Never notifies. */
export async function removeBlocker(
  actor: Actor,
  input: BlockerInput,
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(
    input.orgId,
    issue.id,
    input.blockerId,
  );
}

/** Live blockers of `issueId`, open or closed, ordered by issue number. */
export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return dependencyRepo.listBlockerIssues(orgId, issue.id);
}

/**
 * The completion gate: throws `IssueBlockedError` naming every open blocker
 * when `issueId` has any. Called by every status path before a move to `done`.
 */
export async function assertNotBlocked(
  orgId: OrgId,
  issueId: IssueId,
): Promise<void> {
  const open = await dependencyRepo.listOpenBlockerIds(orgId, issueId);
  if (open.length > 0) {
    throw new IssueBlockedError(issueId, open);
  }
}

/**
 * True when `issueId` is reachable from `from` by following "blocked by"
 * links — i.e. `from` already (transitively) waits on `issueId`. Walks the
 * raw edge set, archived issues included, one level per query.
 */
async function isBlockedTransitively(
  orgId: OrgId,
  from: IssueId,
  issueId: IssueId,
): Promise<boolean> {
  const seen = new Set<IssueId>([from]);
  let frontier: readonly IssueId[] = [from];

  while (frontier.length > 0) {
    const next: IssueId[] = [];
    for (const blockerId of await dependencyRepo.listBlockerIds(
      orgId,
      frontier,
    )) {
      if (blockerId === issueId) return true;
      if (seen.has(blockerId)) continue;
      seen.add(blockerId);
      next.push(blockerId);
    }
    frontier = next;
  }

  return false;
}

/**
 * Runs once a blocker has gone from open to closed. Every issue it blocks
 * that is itself still open, has an assignee and has no open blocker left
 * tells that assignee it can move again.
 */
async function notifyUnblocked(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  const blockedIds = await dependencyRepo.listBlockedIssueIds(orgId, blockerId);

  for (const blockedId of blockedIds) {
    const blocked = await issueRepo.findIssueById(orgId, blockedId);
    if (!blocked || !isOpen(blocked) || blocked.assigneeId === null) continue;

    const open = await dependencyRepo.listOpenBlockerIds(orgId, blocked.id);
    if (open.length > 0) continue;

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "Your issue is unblocked",
      body: `Issue ${blocked.id} has no open blockers left`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}

/**
 * Attached by `event-registry`. A blocker closes either by a status change
 * from an open status into `done`/`canceled`, or by being archived while its
 * status was still open; closed → closed never counts.
 */
export function registerIssueDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      const issue = await issueRepo.findIssueById(
        payload.orgId,
        payload.issueId,
      );
      if (!issue || isClosedStatus(issue.status)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

