 */
async function isBlockedTransitively(
  orgId: OrgId,
  from: IssueId,
  issueId: IssueId,
): Promise<boolean> {
  const seen = new Set<IssueId>([from]);
  let frontier: readonly IssueId[] = [from];

  while (frontier.length > 0) {
    const next: IssueId[] = [];
    for (const blockerId of await dependencyRepo.listBlockerIds(
      orgId,
      frontier,
    )) {
      if (blockerId === issueId) return true;
      if (seen.has(blockerId)) continue;
      seen.add(blockerId);
      next.push(blockerId);
    }
    frontier = next;
  }

  return false;
}

/**
 * Runs once a blocker has gone from open to closed. Every issue it blocks
 * that is itself still open, has an assignee and has no open blocker left
 * tells that assignee it can move again.
 */
async function notifyUnblocked(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  const blockedIds = await dependencyRepo.listBlockedIssueIds(orgId, blockerId);

  for (const blockedId of blockedIds) {
    const blocked = await issueRepo.findIssueById(orgId, blockedId);
    if (!blocked || !isOpen(blocked) || blocked.assigneeId === null) continue;

    const open = await dependencyRepo.listOpenBlockerIds(orgId, blocked.id);
    if (open.length > 0) continue;

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "Your issue is unblocked",
      body: `Issue ${blocked.id} has no open blockers left`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}

/**
 * Attached by `event-registry`. A blocker closes either by a status change
 * from an open status into `done`/`canceled`, or by being archived while its
 * status was still open; closed → closed never counts.
 */
export function registerIssueDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      const issue = await issueRepo.findIssueById(
        payload.orgId,
        payload.issueId,
      );
      if (!issue || isClosedStatus(issue.status)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

