import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("$R/tests/server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("$R/tests/server/_support/doubles/misc")).loggerModule);

import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { NotFoundError } from "@/server/services/_support";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as issueService from "@/server/services/issue-service";
import * as dep from "@/server/services/issue-dependency-service";
import { listNotifications, updatePreference } from "@/server/services/notification-service";
import { updateNotificationPreferenceSchema } from "@/schemas/notification";
import { createTenant, issueInput, useTemporaryDatabase } from "$R/tests/server/_support/fixtures";
import type { Tenant } from "$R/tests/server/_support/fixtures";

let cleanup: () => void;
let t: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  t = await createTenant("deps");
  other = await createTenant("deps2");
  registerEventHandlers();
});
afterAll(() => cleanup());

async function mk(title: string, assigneeId: any = null) {
  return issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id, { title, assigneeId }));
}
async function unblocked(userId: any) {
  const page = await listNotifications(t.actors.owner, { orgId: t.org.id, recipientId: userId, unreadOnly: false, kind: ["issue_unblocked"], limit: 100 } as any);
  return page.items;
}

describe("deps", () => {
  it("basic rules", async () => {
    const a = await mk("Issue A");
    const b = await mk("Issue B");
    const c = await mk("Issue C");
    const actor = t.actors.owner;
    const link = await dep.addBlocker(actor, { orgId: t.org.id, issueId: a.id, blockerId: b.id });
    expect(link).toMatchObject({ orgId: t.org.id, issueId: a.id, blockerId: b.id, createdBy: actor.userId });
    const again = await dep.addBlocker(actor, { orgId: t.org.id, issueId: a.id, blockerId: b.id });
    expect(again).toEqual(link);
    await expect(dep.addBlocker(actor, { orgId: t.org.id, issueId: a.id, blockerId: a.id })).rejects.toThrow();
    await expect(dep.addBlocker(actor, { orgId: t.org.id, issueId: b.id, blockerId: a.id })).rejects.toThrow(/cycle/);
    await dep.addBlocker(actor, { orgId: t.org.id, issueId: b.id, blockerId: c.id });
    await expect(dep.addBlocker(actor, { orgId: t.org.id, issueId: c.id, blockerId: a.id })).rejects.toThrow(/cycle/);
    await expect(dep.addBlocker(t.actors.viewer, { orgId: t.org.id, issueId: c.id, blockerId: a.id })).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(dep.addBlocker(other.actors.owner, { orgId: t.org.id, issueId: c.id, blockerId: a.id })).rejects.toBeInstanceOf(TenantScopeError);
    const x = await issueService.createIssue(other.actors.owner, issueInput(other.org.id, other.project.id, { title: "Other org" }));
    await expect(dep.addBlocker(actor, { orgId: t.org.id, issueId: a.id, blockerId: x.id })).rejects.toBeInstanceOf(NotFoundError);
    await expect(dep.removeBlocker(actor, { orgId: t.org.id, issueId: x.id, blockerId: a.id })).rejects.toBeInstanceOf(NotFoundError);
    expect(await dep.removeBlocker(actor, { orgId: t.org.id, issueId: a.id, blockerId: x.id })).toBe(false);

    const d = await mk("Issue D");
    await dep.addBlocker(actor, { orgId: t.org.id, issueId: a.id, blockerId: d.id });
    expect((await dep.listBlockers(t.actors.viewer, t.org.id, a.id)).map((i) => i.id)).toEqual([b.id, d.id]);

    // gate
    try {
      await issueService.changeIssueStatus(actor, { orgId: t.org.id, issueId: a.id, status: "done" });
      throw new Error("should fail");
    } catch (e) {
      expect(e).toBeInstanceOf(dep.IssueBlockedError);
      expect((e as dep.IssueBlockedError).code).toBe("conflict");
      expect([...(e as dep.IssueBlockedError).blockerIds].sort()).toEqual([b.id, d.id].sort());
    }
    await issueService.changeIssueStatus(actor, { orgId: t.org.id, issueId: d.id, status: "canceled" });
    await expect(issueService.moveIssue(actor, { orgId: t.org.id, issueId: a.id, toStatus: "done", toIndex: 0 })).rejects.toMatchObject({ blockerIds: [b.id] });
    await issueService.changeIssueStatus(actor, { orgId: t.org.id, issueId: a.id, status: "in_review" });

    const archivedIssue = await mk("Archived");
    await issueService.archiveIssue(actor, t.org.id, archivedIssue.id);
    await expect(dep.addBlocker(actor, { orgId: t.org.id, issueId: a.id, blockerId: archivedIssue.id })).rejects.toBeInstanceOf(AlreadyArchivedError);

    expect(await dep.removeBlocker(actor, { orgId: t.org.id, issueId: a.id, blockerId: d.id })).toBe(true);
    expect(await dep.removeBlocker(actor, { orgId: t.org.id, issueId: a.id, blockerId: d.id })).toBe(false);
  });

  it("notifications", async () => {
    const actor = t.actors.owner;
    const member = t.userIds.member;
    const blocked = await mk("Blocked", member);
    const b1 = await mk("Blocker1");
    const b2 = await mk("Blocker2");
    await dep.addBlocker(actor, { orgId: t.org.id, issueId: blocked.id, blockerId: b1.id });
    await dep.addBlocker(actor, { orgId: t.org.id, issueId: blocked.id, blockerId: b2.id });
    await issueService.changeIssueStatus(actor, { orgId: t.org.id, issueId: b1.id, status: "done" });
    expect(await unblocked(member)).toHaveLength(0);
    await issueService.archiveIssue(actor, t.org.id, b2.id);
    let n = await unblocked(member);
    expect(n).toHaveLength(1);
    expect(n[0]).toMatchObject({ href: \`/issues/\${blocked.id}\`, actorId: actor.userId, kind: "issue_unblocked" });
    await issueService.changeIssueStatus(actor, { orgId: t.org.id, issueId: b1.id, status: "canceled" });
    expect(await unblocked(member)).toHaveLength(1);
    await issueService.changeIssueStatus(actor, { orgId: t.org.id, issueId: b1.id, status: "todo" });
    await issueService.changeIssueStatus(actor, { orgId: t.org.id, issueId: b1.id, status: "done" });
    expect(await unblocked(member)).toHaveLength(2);
    // own action
    await issueService.changeIssueStatus(actor, { orgId: t.org.id, issueId: b1.id, status: "todo" });
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: b1.id, status: "done" });
    expect(await unblocked(member)).toHaveLength(2);
    // muted
    const pref = updateNotificationPreferenceSchema.parse({ orgId: t.org.id, userId: member, kind: "issue_unblocked", inApp: false, email: false, digestOnly: false });
    await updatePreference(t.actors.member, pref);
    await issueService.changeIssueStatus(actor, { orgId: t.org.id, issueId: b1.id, status: "todo" });
    await issueService.changeIssueStatus(actor, { orgId: t.org.id, issueId: b1.id, status: "done" });
    expect(await unblocked(member)).toHaveLength(2);
    await issueService.changeIssueStatus(actor, { orgId: t.org.id, issueId: blocked.id, status: "done" });
  });
});
EOF
