    await dep.addBlocker(actor, { orgId: t.org.id, issueId: blocked.id, blockerId: b2.id });
    await issueService.changeIssueStatus(actor, { orgId: t.org.id, issueId: b1.id, status: "done" });
    expect(await unblocked(member)).toHaveLength(0);
    await issueService.archiveIssue(actor, t.org.id, b2.id);
    let n = await unblocked(member);
    expect(n).toHaveLength(1);
    expect(n[0]).toMatchObject({ href: \`/issues/\${blocked.id}\`, actorId: actor.userId, kind: "issue_unblocked" });
    await issueService.changeIssueStatus(actor, { orgId: t.org.id, issueId: b1.id, status: "canceled" });
    expect(await unblocked(member)).toHaveLength(1);
    await issueService.changeIssueStatus(actor, { orgId: t.org.id, issueId: b1.id, status: "todo" });
    await issueService.changeIssueStatus(actor, { orgId: t.org.id, issueId: b1.id, status: "done" });
    expect(await unblocked(member)).toHaveLength(2);
    // own action
    await issueService.changeIssueStatus(actor, { orgId: t.org.id, issueId: b1.id, status: "todo" });
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: b1.id, status: "done" });
    expect(await unblocked(member)).toHaveLength(2);
    // muted
    const pref = updateNotificationPreferenceSchema.parse({ orgId: t.org.id, userId: member, kind: "issue_unblocked", inApp: false, email: false, digestOnly: false });
    await updatePreference(t.actors.member, pref);
    await issueService.changeIssueStatus(actor, { orgId: t.org.id, issueId: b1.id, status: "todo" });
    await issueService.changeIssueStatus(actor, { orgId: t.org.id, issueId: b1.id, status: "done" });
    expect(await unblocked(member)).toHaveLength(2);
    await issueService.changeIssueStatus(actor, { orgId: t.org.id, issueId: blocked.id, status: "done" });
  });
});
